			id TEXT NOT NULL,
			kind TEXT NOT NULL,
			branch TEXT NOT NULL,
			path TEXT NOT NULL,
			line INTEGER NOT NULL,
			summary TEXT NOT NULL,
			terms_json TEXT NOT NULL,
			CHECK(fts_rowid = rec_order + 1)
		);
CREATE VIRTUAL TABLE history_fts USING fts5(content, content='', tokenize='porter unicode61')
