diff --git a/internal/cli/agent_surface.go b/internal/cli/agent_surface.go
index 293fd44c0..0ee9f945d 100644
--- a/internal/cli/agent_surface.go
+++ b/internal/cli/agent_surface.go
@@ -108,6 +108,15 @@ type brainStatusReport struct {
 	// deliberately not part of the JSON contract: it duplicates the structured
 	// sections above and its session list scales with brain size.
 	Manifest *exportManifest `json:"-"`
+	// graphStoreErr is the store probe's verdict, kept for in-process consumers:
+	// when it is errGraphStoreUnavailable the provider itself said "no store for
+	// this commit", and the brief uses that to not ask again (COR-2314). The
+	// probe always runs the DEFAULT `entire` binary, so the verdict only speaks
+	// for that binary.
+	graphStoreErr error
+	// graphStoreDetail is the provider's own detail for that refusal — bare, so
+	// warnings can carry its remedy without the probe error's wrapping.
+	graphStoreDetail string
 }

 type brainStatusFacts struct {
@@ -1506,7 +1515,20 @@ func runBrainBrief(ctx context.Context, cmd *cobra.Command, opts Options, briefO
 	semanticDelegated := false
 	graphStoreMissing := false
 	var graphStoreMissingDetail string
-	{
+	// The status build above already asked the provider for its store. When
+	// the provider itself answered "no store for this commit" and cannot serve
+	// an ancestor answer either, `graph context` would spawn a subprocess only
+	// to repeat that refusal — at real corpus sizes it was half the brief's
+	// wall clock (COR-2314). The probe's own detail keeps carrying the remedy.
+	// The probe ran the DEFAULT binary, so its refusal speaks only for that
+	// binary: a --graph-binary override is always asked.
+	briefGraphBinary := strings.TrimSpace(briefOpts.graphBinary)
+	if errors.Is(status.graphStoreErr, errGraphStoreUnavailable) &&
+		(briefGraphBinary == "" || briefGraphBinary == "entire") &&
+		!(graphBriefAncestorBudget > 0 && graphContextAllowsAncestor(ctx, opts.Runner, status.Repo.Root, briefOpts.graphBinary)) {
+		graphStoreMissing = true
+		graphStoreMissingDetail = status.graphStoreDetail
+	} else {
 		delegationStarted := profile.start()
 		graphContext, graphErr := fetchGraphTaskContext(ctx, opts.Runner, status.Repo.Root, briefOpts.graphBinary, task, briefOpts.limit, briefOpts.limit)
 		if graphErr == nil && graphContext.StoreUnavailable {
@@ -4493,6 +4515,8 @@ func buildBrainStatusReportWithAvailability(ctx context.Context, opts Options, t
 	// outright -- is a different, actionable problem, and used to vanish along
 	// with the ordinary case. That one is recorded as a warning instead.
 	var graphStatusWarning string
+	var graphStoreErr error
+	var graphStoreDetail string
 	if layoutErr := checkLegacyBrainLayout(storage.BrainDir, manifest); layoutErr != nil {
 		graphStatusWarning = layoutErr.Error()
 		code := brainstore.MemoryErrorCode(layoutErr)
@@ -4510,6 +4534,8 @@ func buildBrainStatusReportWithAvailability(ctx context.Context, opts Options, t
 		// Do not replace the old source with a healthy Graph descriptor.
 		if graphStatusWarning == "" {
 			if d, graphErr := fetchGraphStore(ctx, opts, repoDir, "", profile); graphErr != nil {
+				graphStoreErr = graphErr
+				graphStoreDetail = strings.TrimSpace(d.Detail)
 				if !errors.Is(graphErr, errGraphStoreUnsupported) && !errors.Is(graphErr, errGraphStoreUnavailable) {
 					graphStatusWarning = "graph store unavailable: " + graphErr.Error()
 				}
@@ -4527,8 +4553,10 @@ func buildBrainStatusReportWithAvailability(ctx context.Context, opts Options, t
 			SupportedSchema: bmanifest.SchemaVersion,
 			ManifestState:   manifestState,
 		},
-		Manifest: manifest,
-		Issues:   healthIssues,
+		Manifest:         manifest,
+		Issues:           healthIssues,
+		graphStoreErr:    graphStoreErr,
+		graphStoreDetail: graphStoreDetail,
 	}
 	if graphStatusWarning != "" {
 		report.Warnings = append(report.Warnings, graphStatusWarning)
diff --git a/internal/cli/blind_spot.go b/internal/cli/blind_spot.go
index 50aff5a6a..f0f511116 100644
--- a/internal/cli/blind_spot.go
+++ b/internal/cli/blind_spot.go
@@ -57,6 +57,16 @@ func emptyResultBlindSpotOnBranch(brainDir, branch string) string {
 	if err != nil || manifest == nil || manifest.Sources == nil {
 		return noBrainBlindSpot(err)
 	}
+	return emptyResultBlindSpotWithIntegrity(brainDir, branch, manifest, factstore.Inspect(brainDir, manifest.Sources.Facts))
+}
+
+// emptyResultBlindSpotWithIntegrity is emptyResultBlindSpotOnBranch for a
+// caller that already loaded the manifest and inspected the store this
+// invocation: it re-reads neither, trusting the verdict it was handed.
+func emptyResultBlindSpotWithIntegrity(brainDir, branch string, manifest *exportManifest, integrity factstore.Integrity) string {
+	if manifest == nil || manifest.Sources == nil {
+		return noBrainBlindSpot(nil)
+	}
 	// Every branch below EXPLAINS an absence, and each explanation is false
 	// when the facts were stored and the store lost them. The last one —
 	// "the answer may genuinely not be in the brain" — is the most damaging
@@ -66,7 +76,7 @@ func emptyResultBlindSpotOnBranch(brainDir, branch string) string {
 	//
 	// This single choke point is why recall, search, query and retrieve all
 	// inherit the correction without each having to remember to ask.
-	if integrity := factstore.Inspect(brainDir, manifest.Sources.Facts); !integrity.OK() {
+	if !integrity.OK() {
 		return "note: this empty result is NOT evidence of absence — " + integrity.Warning()
 	}
 	// A connected repo whose branch never synced may be missing the whole
diff --git a/internal/cli/blind_spot_test.go b/internal/cli/blind_spot_test.go
index 2d8e0df2b..9df0d5862 100644
--- a/internal/cli/blind_spot_test.go
+++ b/internal/cli/blind_spot_test.go
@@ -5,6 +5,7 @@ import (
 	"testing"
 	"time"

+	"github.com/entireio/entire-brain/internal/cli/internal/factstore"
 	bmanifest "github.com/entireio/entire-brain/internal/cli/internal/manifest"
 )

@@ -50,3 +51,31 @@ func TestEmptyResultBlindSpot(t *testing.T) {
 		t.Fatalf("missing manifest must name the missing brain, got %q", note)
 	}
 }
+
+// The precomputed-integrity variant exists so read surfaces that already
+// loaded and inspected the store once do not read it again for the empty-result
+// note. It must trust the caller's verdict, not recompute its own.
+func TestEmptyResultBlindSpotWithIntegrityUsesCallerVerdict(t *testing.T) {
+	now := time.Date(2026, 6, 10, 12, 0, 0, 0, time.UTC)
+	brainDir := writeDistillFixture(t, now)
+	manifest, err := bmanifest.Load(brainDir)
+	if err != nil {
+		t.Fatal(err)
+	}
+
+	// A caller that saw loss must get the loss note, even though re-inspecting
+	// this brain's (empty, healthy) store would say nothing is wrong.
+	lossy := factstore.Integrity{Declared: 5, Readable: 2, Distinct: 2, Mode: factstore.DefectLossy}
+	note := emptyResultBlindSpotWithIntegrity(brainDir, "main", manifest, lossy)
+	if !strings.Contains(note, "NOT evidence of absence") || !strings.Contains(note, lossy.Warning()) {
+		t.Fatalf("lossy integrity must produce the loss note, got %q", note)
+	}
+
+	// A healthy verdict must fall through to the same coverage note the
+	// re-inspecting surface produces.
+	want := emptyResultBlindSpot(brainDir)
+	got := emptyResultBlindSpotWithIntegrity(brainDir, "", manifest, factstore.Integrity{})
+	if got != want {
+		t.Fatalf("healthy integrity must match the re-inspecting note:\n got %q\nwant %q", got, want)
+	}
+}
